// Basic creation
ScreenImageMgr.createScreenImage("logo", "logo.png", 10, 10, 1.0, true, 1.0, 1.0);

// Semi-transparent watermark in bottom-right corner
var sw = core.getScreenWidth();
var sh = core.getScreenHeight();
ScreenImageMgr.createScreenImage("wm", "watermark.png", sw - 200, sh - 100, 0.8, true, 0.5, 2.0);

// Hidden image that will fade in later (fadeDuration=0.5s)
ScreenImageMgr.createScreenImage("overlay", "overlay.png", 100, 100, 1.0, false, 1.0, 0.5);
ScreenImageMgr.showImage("overlay", true);  // fades in over 0.5s

// Cleanup
ScreenImageMgr.deleteImage("logo");
ScreenImageMgr.deleteImage("wm");
ScreenImageMgr.deleteImage("overlay");

if(ScreenImageMgr.getShowImage("logo")) {
    core.debug("Logo is visible");
} else {
    core.debug("Logo is hidden or does not exist");
}

// Toggle pattern
ScreenImageMgr.showImage("logo", !ScreenImageMgr.getShowImage("logo"));

// Hide then re-show with fade
ScreenImageMgr.showImage("logo", false);
core.wait(2);
ScreenImageMgr.showImage("logo", true);

// Toggle
ScreenImageMgr.showImage("logo", !ScreenImageMgr.getShowImage("logo"));

// Sequence: fade in three images one after another
var ids = ["img1", "img2", "img3"];
for (var i = 0; i < ids.length; i++) {
    ScreenImageMgr.createScreenImage(ids[i], ids[i] + ".png", 100, 100 + i*120, 1.0, false, 1.0, 0.5);
}
for (var i = 0; i < ids.length; i++) {
    ScreenImageMgr.showImage(ids[i], true);
    core.wait(1);
}

// Cleanup
for (var i = 0; i < ids.length; i++) {
    ScreenImageMgr.deleteImage(ids[i]);
}

var baseW = ScreenImageMgr.getImageWidth("logo");
var sx = ScreenImageMgr.getImageScaleX("logo");
var onScreenW = baseW * sx;
core.debug("Base: " + baseW + " px, scale X: " + sx + ", on-screen: " + onScreenW + " px");

// Center based on base size (only correct if scaleX == 1)
var sw = core.getScreenWidth();
var sh = core.getScreenHeight();
var h = ScreenImageMgr.getImageHeight("logo");
ScreenImageMgr.setImageXY("logo", (sw - baseW*sx)/2, (sh - h*ScreenImageMgr.getImageScaleY("logo"))/2, 0);

var baseH = ScreenImageMgr.getImageHeight("logo");
var sy = ScreenImageMgr.getImageScaleY("logo");
core.debug("Base height: " + baseH + ", on-screen: " + (baseH * sy) + " px");

var sx = ScreenImageMgr.getImageScaleX("logo");
var sy = ScreenImageMgr.getImageScaleY("logo");
core.debug("Target scale: " + sx + " x " + sy);

if (Math.abs(sx - sy) > 0.01) {
    core.debug("Image is non-uniformly scaled");
}

// NOTE: during an animation this returns the target, not the current value
ScreenImageMgr.setImageScale("logo", 2.0, 2.0, 3.0);
core.debug("During animation, target is already: " + ScreenImageMgr.getImageScaleX("logo"));

// Zoom in over 2 seconds
ScreenImageMgr.setImageScale("logo", 2.0, 2.0, 2.0);
core.wait(2);

// Shrink back over 1 second
ScreenImageMgr.setImageScale("logo", 0.5, 0.5, 1.0);
core.wait(1);

// Stretch horizontally only
ScreenImageMgr.setImageScale("logo", 3.0, 1.0, 1.5);
core.wait(1.5);

// Read back the TARGET (not the current value during animation)
core.debug("Target scale X: " + ScreenImageMgr.getImageScaleX("logo"));

// Reset
ScreenImageMgr.setImageScale("logo", 1.0, 1.0, 0);

// Make semi-transparent
ScreenImageMgr.setImageAlpha("logo", 0.6);

// Fully opaque
ScreenImageMgr.setImageAlpha("logo", 1.0);

// Manual fade-out by stepping alpha (NOTE: instant steps, not smooth)
function fadeOutManual(id, steps, stepDelay) {
    for (var i = steps; i >= 0; i--) {
        ScreenImageMgr.setImageAlpha(id, i / steps);
        core.wait(stepDelay);
    }
    ScreenImageMgr.showImage(id, false);
}
fadeOutManual("logo", 10, 0.1);

// Restore
ScreenImageMgr.setImageAlpha("logo", 1.0);

// Instant move to top-right
var sw = core.getScreenWidth();
var w = ScreenImageMgr.getImageWidth("logo") * ScreenImageMgr.getImageScaleX("logo");
ScreenImageMgr.setImageXY("logo", sw - w - 10, 10, 0);

// Animated move to center over 1 second
var sh = core.getScreenHeight();
var h = ScreenImageMgr.getImageHeight("logo") * ScreenImageMgr.getImageScaleY("logo");
ScreenImageMgr.setImageXY("logo", (sw - w)/2, (sh - h)/2, 1.0);
core.wait(1);

// Slide-in from right
ScreenImageMgr.setImageXY("logo", sw, 100, 0);
ScreenImageMgr.showImage("logo", true);
ScreenImageMgr.setImageXY("logo", sw - w - 10, 100, 1.5);

// Move 100 px right and 50 px down over 1s
ScreenImageMgr.addImageXY("logo", 100, 50, 1.0);
core.wait(1);

// Simple bounce loop
for (var i = 0; i < 3; i++) {
    ScreenImageMgr.addImageXY("logo", 0, -20, 0.2);
    core.wait(0.2);
    ScreenImageMgr.addImageXY("logo", 0, 20, 0.2);
    core.wait(0.2);
}

// Return to approximate original position (relative undo)
ScreenImageMgr.addImageXY("logo", -100, -50, 1.0);

// Delete one image
ScreenImageMgr.deleteImage("logo");

// Safe delete (check first)
var ids = ScreenImageMgr.getAllImageIDs();
if (ids.indexOf("logo") >= 0) {
    ScreenImageMgr.deleteImage("logo");
}

// Delete all images whose ID starts with 'temp_'
var all = ScreenImageMgr.getAllImageIDs();
for (var i = 0; i < all.length; i++) {
    if (all[i].indexOf("temp_") === 0) {
        ScreenImageMgr.deleteImage(all[i]);
    }
}

// Count before cleanup
var count = ScreenImageMgr.getAllImageIDs().length;
core.debug("Images before: " + count);

// Clear everything
ScreenImageMgr.deleteAllImages();
core.debug("Images after: " + ScreenImageMgr.getAllImageIDs().length);

// Typical end-of-script cleanup
function runSlideshow() {
    ScreenImageMgr.createScreenImage("slide1", "slide1.png", 0, 0);
    core.wait(3);
    ScreenImageMgr.createScreenImage("slide2", "slide2.png", 0, 0);
    core.wait(3);
    ScreenImageMgr.deleteAllImages();
}
runSlideshow();

var ids = ScreenImageMgr.getAllImageIDs();
core.debug("Total images: " + ids.length);
for (var i = 0; i < ids.length; i++) {
    core.debug((i+1) + ". " + ids[i]);
}

// Hide all images
for (var i = 0; i < ids.length; i++) {
    ScreenImageMgr.showImage(ids[i], false);
}

// Existence check helper
function imageExists(id) {
    return ScreenImageMgr.getAllImageIDs().indexOf(id) >= 0;
}
if (imageExists("logo")) {
    core.debug("Logo exists");
} else {
    ScreenImageMgr.createScreenImage("logo", "logo.png", 10, 10);
}
